// Patnitop Travels Hub — website assistant (v3)
// Rule-based chat. It is NOT a language-model chatbot: there is no external
// API, no API key and no paid service. It can only say what is in
// window.AGENT_DATA (generated by build.py from the same content as the pages).
//
// Customers can use buttons, or describe the trip in their own words; the
// assistant picks out what it can (places, date, people, vehicle, phone) and
// asks only for what is missing. Everything is shown back for confirmation
// before anything is sent.
//
// Hard rules built into the code:
//   * A fare is shown only if (a) the pickup and drop are the two ends of a
//     route that has a verified rate, (b) the rate is in data/rates.json with
//     a verification date and name, and (c) it is under 90 days old.
//     Otherwise: "Dileep will confirm the fare" - never a guess.
//   * It never confirms a booking or promises vehicle / hotel availability.
//   * Every enquiry ends in a real WhatsApp / phone hand-off to a person.
//   * Taxi enquiries and local-product enquiries are separate flows.
//   * A lead is recorded only after the customer confirms the summary and
//     taps WhatsApp or "Send my details".

(function () {
  'use strict';
  if (typeof AGENT_DATA === 'undefined') return; // fail silently, rest of site unaffected

  var WA_NUMBER = AGENT_DATA.whatsappNumber;
  var PHONE = AGENT_DATA.phone;
  var RATE_MAX_AGE_DAYS = 90; // older verified rates are not quoted
  var MAX_DAYS_AHEAD = 548;   // ~18 months
  var PRIVACY = AGENT_DATA.privacyPath || 'privacy.html';

  function waLink(message) {
    return 'https://wa.me/' + WA_NUMBER + '?text=' + encodeURIComponent(message);
  }
  function track(name, params) {
    if (typeof window.ptvTrack === 'function') window.ptvTrack(name, params || {});
  }
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c];
    });
  }
  function pad2(n) { return String(n).padStart(2, '0'); }
  function isoOf(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
  function startOfToday() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
  function todayISO() { return isoOf(startOfToday()); }
  function addDays(d, n) { return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n); }

  // ---------------------------------------------------------------
  // Widget DOM — built once, injected at the end of <body>
  // ---------------------------------------------------------------
  var root = document.createElement('div');
  root.id = 'ptv-agent-root';

  root.innerHTML =
    '<button id="ptv-agent-launcher" type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="ptv-agent-panel" aria-label="Open chat assistant">' +
      '<span class="ptv-agent-launcher-icon" aria-hidden="true">💬</span>' +
    '</button>' +
    '<div id="ptv-agent-panel" role="dialog" aria-modal="false" aria-label="Patnitop Travels Hub assistant" hidden>' +
      '<div class="ptv-agent-header">' +
        '<span class="ptv-agent-title">Patnitop Travels Hub</span>' +
        '<button id="ptv-agent-close" type="button" aria-label="Close chat">&times;</button>' +
      '</div>' +
      '<div class="ptv-agent-body" id="ptv-agent-body" aria-live="polite"></div>' +
      '<div class="ptv-agent-footer">' +
        '<a id="ptv-agent-wa-persistent" class="btn btn-whatsapp ptv-agent-wa-small" href="' + waLink('Hello Patnitop Travels Hub, I would like to enquire about a taxi/hotel booking.') + '" target="_blank" rel="noopener">💬 Chat on WhatsApp</a>' +
        '<a class="btn btn-pine ptv-agent-wa-small" href="tel:+91' + PHONE + '">📞 Call</a>' +
      '</div>' +
    '</div>';

  document.body.appendChild(root);

  var launcher = document.getElementById('ptv-agent-launcher');
  var panel = document.getElementById('ptv-agent-panel');
  var body = document.getElementById('ptv-agent-body');
  var closeBtn = document.getElementById('ptv-agent-close');

  // ---------------------------------------------------------------
  // Open / close
  // ---------------------------------------------------------------
  var opened = false;

  function openPanel() {
    panel.hidden = false;
    launcher.setAttribute('aria-expanded', 'true');
    if (!opened) {
      opened = true;
      renderGreeting();
    }
    closeBtn.focus();
  }

  function closePanel() {
    panel.hidden = true;
    launcher.setAttribute('aria-expanded', 'false');
    launcher.focus();
  }

  launcher.addEventListener('click', function () {
    if (panel.hidden) openPanel(); else closePanel();
  });
  closeBtn.addEventListener('click', closePanel);

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !panel.hidden) closePanel();
  });

  // ---------------------------------------------------------------
  // Rendering helpers
  // ---------------------------------------------------------------
  function el(tag, cls, html) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  function scrollDown() { body.scrollTop = body.scrollHeight; }
  function clearBody() { body.innerHTML = ''; }

  function addBotMessage(html) {
    body.appendChild(el('div', 'ptv-msg ptv-msg-bot', html));
    scrollDown();
  }

  function addUserMessage(text) {
    var msg = el('div', 'ptv-msg ptv-msg-user');
    msg.textContent = text;
    body.appendChild(msg);
    scrollDown();
  }

  // A row of quick-reply buttons. options = [{label, onClick, primary}]
  function addButtons(options) {
    var wrap = el('div', 'ptv-btn-row');
    options.forEach(function (opt) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'ptv-choice-btn' + (opt.primary ? ' ptv-primary' : '');
      b.textContent = opt.label;
      b.addEventListener('click', function () {
        addUserMessage(opt.label);
        wrap.querySelectorAll('button').forEach(function (btn) { btn.disabled = true; });
        opt.onClick();
      });
      wrap.appendChild(b);
    });
    body.appendChild(wrap);
    scrollDown();
    return wrap;
  }

  // A single input with a submit button.
  // opts: {type, placeholder, min, inputMode, validate(raw) -> {value}|{error}, onSubmit(value), button}
  function addInput(opts) {
    var wrap = el('div', 'ptv-input-row');
    var input = document.createElement('input');
    input.type = opts.type || 'text';
    input.placeholder = opts.placeholder || '';
    input.setAttribute('aria-label', opts.placeholder || 'Your answer');
    if (opts.min) input.min = opts.min;
    if (opts.inputMode) input.inputMode = opts.inputMode;
    if (opts.autocomplete) input.autocomplete = opts.autocomplete;
    if (opts.maxLength) input.maxLength = opts.maxLength;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'ptv-choice-btn ptv-input-submit';
    btn.textContent = opts.button || 'Next →';
    var err = el('div', 'ptv-error');
    err.setAttribute('role', 'alert');

    function submit() {
      var raw = input.value.trim();
      if (!raw) { input.focus(); return; }
      var value = raw;
      if (opts.validate) {
        var res = opts.validate(raw);
        if (res.error) { err.textContent = res.error; input.focus(); return; }
        value = res.value;
      }
      err.textContent = '';
      addUserMessage(raw);
      input.disabled = true;
      btn.disabled = true;
      opts.onSubmit(value);
    }
    btn.addEventListener('click', submit);
    input.addEventListener('keydown', function (e) { if (e.key === 'Enter') submit(); });

    wrap.appendChild(input);
    wrap.appendChild(btn);
    body.appendChild(wrap);
    body.appendChild(err);
    scrollDown();
    setTimeout(function () { input.focus(); }, 50);
    return wrap;
  }

  function backToMenuButton() {
    addButtons([{ label: '⬅ Main Menu', onClick: renderMainMenu }]);
  }

  function whatsAppFallback(message) {
    var link = el('a', 'btn btn-whatsapp ptv-inline-wa', '💬 Continue on WhatsApp');
    link.href = waLink(message);
    link.target = '_blank';
    link.rel = 'noopener';
    body.appendChild(link);
    scrollDown();
  }

  // ---------------------------------------------------------------
  // Greeting + main menu
  // ---------------------------------------------------------------
  function renderGreeting() {
    clearBody();
    addBotMessage('Hi! 👋 Welcome to Patnitop Travels Hub. Tell me about your trip in your own words, or pick an option below.');
    renderMainMenuButtonsOnly();
  }

  function renderMainMenu() {
    addBotMessage('What would you like to do?');
    renderMainMenuButtonsOnly();
  }

  function renderMainMenuButtonsOnly() {
    addButtons([
      { label: '✍️ Describe my trip', primary: true, onClick: startDescribeFlow },
      { label: '🚕 Book a Taxi', onClick: renderTaxiMenu },
      { label: '🏔️ Patnitop Sightseeing', onClick: renderSightseeing },
      { label: '🏨 Hotel Booking', onClick: renderHotels },
      { label: '📦 Tour Packages', onClick: renderPackages },
      { label: '🚗 Vehicles', onClick: renderVehicles },
      { label: '🛍️ Local Products Enquiry', onClick: renderProducts },
      { label: '❓ Ask a Question', onClick: renderFaqMenu },
      { label: '💬 Chat on WhatsApp', onClick: function () {
          addBotMessage('Sure — tap below to continue on WhatsApp.');
          whatsAppFallback('Hello Patnitop Travels Hub, I would like to enquire about a taxi/hotel booking.');
          backToMenuButton();
        } },
    ]);
  }

  // ---------------------------------------------------------------
  // Validators — every one returns {value} or {error}
  // ---------------------------------------------------------------
  function vName(raw) {
    var v = raw.replace(/\s+/g, ' ').trim();
    if (v.length < 2 || v.length > 60 || !/[A-Za-zऀ-ॿ]/.test(v)) return { error: 'Please enter your name (2 to 60 characters).' };
    return { value: v };
  }
  function vMobile(raw) {
    var cleaned = window.ptvLead ? window.ptvLead.cleanMobile(raw) : raw.replace(/\D/g, '');
    return cleaned ? { value: cleaned } : { error: 'Please enter a valid mobile number (10 to 15 digits).' };
  }
  function vDate(raw) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
    if (!m) return { error: 'Please choose a date from the calendar.' };
    var d = new Date(+m[1], +m[2] - 1, +m[3]);
    if (isoOf(d) !== raw) return { error: 'That date does not exist. Please choose another.' };
    var today = startOfToday();
    if (d < today) return { error: 'That date has already passed. Please choose today or a later date.' };
    if (d > addDays(today, MAX_DAYS_AHEAD)) return { error: 'Please choose a date within the next 18 months.' };
    return { value: raw };
  }
  function vPlace(raw) {
    var v = raw.replace(/\s+/g, ' ').trim();
    if (v.length < 2 || v.length > 80) return { error: 'Please enter a place name (2 to 80 characters).' };
    return { value: v };
  }
  function vPeople(raw) {
    var n = parseInt(raw, 10);
    return (/^\d{1,2}$/.test(raw) && n >= 1 && n <= 60) ? { value: String(n) } : { error: 'Please enter a number between 1 and 60.' };
  }
  function vText(raw) {
    var v = raw.replace(/\s+/g, ' ').trim();
    return v.length > 300 ? { error: 'Please keep this under 300 characters.' } : { value: v };
  }

  // ---------------------------------------------------------------
  // Vehicles and capacity (from the facts already on vehicles.html)
  // ---------------------------------------------------------------
  function vehicleByName(name) {
    return AGENT_DATA.vehicles.filter(function (v) { return v.name === name; })[0] || null;
  }
  function capacityWarning(a) {
    var v = vehicleByName(a.vehicle);
    var n = parseInt(a.passengers, 10);
    if (v && v.capacity && n > v.capacity) {
      return 'A ' + v.name + ' seats up to ' + v.capacity + ' (see our vehicle details), and you listed ' + n + ' passengers. Dileep will suggest a suitable vehicle — or choose a larger one.';
    }
    return '';
  }

  // ---------------------------------------------------------------
  // The enquiry model.
  //   E = { a: answers, seq: [field keys in order], meta: {type, ...} }
  // Each field has an asker. run(E) asks the first field with no answer,
  // so pre-filled answers (from the customer's own words) are skipped and
  // "change something" simply clears one answer and runs again.
  // ---------------------------------------------------------------
  var ASK = {
    name: function (E, next) {
      addBotMessage('What name should I note down?');
      addInput({ placeholder: 'Your name', autocomplete: 'name', validate: vName, onSubmit: function (v) { E.a.name = v; next(); } });
    },
    mobile: function (E, next) {
      addBotMessage('Your mobile number, so Dileep can reach you? We use it only to answer this enquiry (<a href="' + escapeHtml(PRIVACY) + '" target="_blank" rel="noopener">privacy notice</a>).');
      addInput({ type: 'tel', inputMode: 'tel', autocomplete: 'tel', placeholder: 'Mobile number', validate: vMobile, onSubmit: function (v) { E.a.mobile = v; next(); } });
    },
    date: function (E, next) {
      addBotMessage(escapeHtml(E.meta.dateQuestion || 'What is your travel date?'));
      addInput({ type: 'date', min: todayISO(), placeholder: 'Travel date', validate: vDate, onSubmit: function (v) { E.a.date = v; next(); } });
    },
    pickup: function (E, next) {
      var hint = E.meta.pickupHint ? ' (e.g. ' + E.meta.pickupHint + ')' : '';
      addBotMessage('Pickup location?' + escapeHtml(hint));
      addInput({ placeholder: 'Pickup location', validate: vPlace, onSubmit: function (v) { E.a.pickup = v; next(); } });
    },
    drop: function (E, next) {
      var hint = E.meta.dropHint ? ' (e.g. ' + E.meta.dropHint + ')' : '';
      addBotMessage('Drop location?' + escapeHtml(hint));
      addInput({
        placeholder: 'Drop location',
        validate: function (raw) {
          var r = vPlace(raw);
          if (!r.error && E.a.pickup && r.value.toLowerCase() === E.a.pickup.toLowerCase()) return { error: 'Pickup and drop are the same place. Please enter the drop location.' };
          return r;
        },
        onSubmit: function (v) { E.a.drop = v; next(); }
      });
    },
    passengers: function (E, next) {
      addBotMessage(E.meta.type === 'taxi' ? 'How many passengers?' : 'How many people is this for?');
      addInput({ type: 'number', inputMode: 'numeric', placeholder: 'Number of people', min: '1', validate: vPeople, onSubmit: function (v) { E.a.passengers = v; next(); } });
    },
    vehicle: function (E, next) {
      addBotMessage('Any vehicle preference?');
      var opts = AGENT_DATA.vehicles.map(function (v) {
        return { label: v.name, onClick: function () { E.a.vehicle = v.name; next(); } };
      });
      opts.push({ label: 'Not sure — please suggest', onClick: function () { E.a.vehicle = 'Not sure — please suggest'; next(); } });
      addButtons(opts);
    },
    tripType: function (E, next) {
      addBotMessage('One-way drop or round trip?');
      addButtons([
        { label: 'One-way', onClick: function () { E.a.tripType = 'one-way'; next(); } },
        { label: 'Round trip', onClick: function () { E.a.tripType = 'round-trip'; next(); } },
        { label: 'Not sure', onClick: function () { E.a.tripType = 'not sure'; next(); } },
      ]);
    },
    sightseeing: function (E, next) {
      addBotMessage('Would you like local sightseeing added to this trip?');
      addButtons([
        { label: 'Yes', onClick: function () { E.a.sightseeing = 'Yes'; next(); } },
        { label: 'No', onClick: function () { E.a.sightseeing = 'No'; next(); } },
      ]);
    },
    hotel: function (E, next) {
      addBotMessage('Do you need help with hotel booking in Patnitop too?');
      addButtons([
        { label: 'Yes', onClick: function () { E.a.hotel = 'Yes'; next(); } },
        { label: 'No', onClick: function () { E.a.hotel = 'No'; next(); } },
      ]);
    },
    products: function (E, next) {
      addBotMessage('Which products are you interested in? (e.g. ' + escapeHtml(AGENT_DATA.productInterests.slice(0, 3).join(', ').toLowerCase()) + ')');
      addInput({ placeholder: 'Products', validate: vText, onSubmit: function (v) { E.a.products = v; next(); } });
    },
    note: function (E, next) {
      addBotMessage(escapeHtml(E.meta.noteQuestion || 'Anything specific you would like us to know? (or type "none")'));
      addInput({ placeholder: 'Details', validate: vText, onSubmit: function (v) { E.a.note = v; next(); } });
    },
    consent: function (E, next) {
      addBotMessage('May we follow up with you by call or WhatsApp about this enquiry if needed?');
      addButtons([
        { label: 'Yes, you may follow up', onClick: function () { E.a.consent = 'Yes'; next(); } },
        { label: "No, I'll contact you", onClick: function () { E.a.consent = 'No'; next(); } },
      ]);
    },
  };

  var ORDER = ['service', 'name', 'mobile', 'date', 'pickup', 'drop', 'passengers', 'vehicle', 'tripType', 'sightseeing', 'hotel', 'products', 'note', 'consent'];
  var LABELS = {
    service: 'Service', name: 'Name', mobile: 'Mobile', date: 'Date', pickup: 'Pickup', drop: 'Drop',
    passengers: 'Passengers', vehicle: 'Vehicle', tripType: 'Trip type', sightseeing: 'Sightseeing',
    hotel: 'Hotel required', products: 'Products', note: 'Notes', consent: 'OK to follow up'
  };

  function run(E) {
    var key = null;
    for (var i = 0; i < E.seq.length; i++) { if (E.a[E.seq[i]] === undefined) { key = E.seq[i]; break; } }
    if (key === null) { renderConfirm(E); return; }
    ASK[key](E, function () { run(E); });
  }

  function taxiSeq(opts) {
    var seq = ['name', 'mobile', 'date', 'pickup', 'drop', 'passengers', 'vehicle', 'tripType'];
    if (opts.sightseeing) seq.push('sightseeing');
    if (opts.hotel) seq.push('hotel');
    seq.push('consent');
    return seq;
  }

  // ---------------------------------------------------------------
  // Taxi menu → route → enquiry
  // ---------------------------------------------------------------
  function renderTaxiMenu() {
    addBotMessage('Which taxi service do you need?');
    var opts = AGENT_DATA.routes.map(function (r) {
      return { label: r.label, onClick: function () { renderRouteInfo(r); } };
    });
    opts.push({ label: '⬅ Main Menu', onClick: renderMainMenu });
    addButtons(opts);
  }

  function renderRouteInfo(route) {
    addBotMessage('<strong>' + escapeHtml(route.label) + '</strong><br>' + escapeHtml(route.summary));
    addButtons([
      { label: '📝 Start Enquiry', primary: true, onClick: function () { startBookingFlow(route); } },
      { label: '⬅ Back to Taxi Options', onClick: renderTaxiMenu },
    ]);
  }

  function startBookingFlow(route) {
    var E = {
      a: { service: route.label },
      seq: taxiSeq({ sightseeing: route.askSightseeing, hotel: route.askHotel }),
      meta: { type: 'taxi', pickupHint: route.defaultPickup, dropHint: route.defaultDrop }
    };
    if (route.id === 'nathatop-sanasar') E.a.tripType = 'local-sightseeing';
    addBotMessage("Great — let's get a few details for your " + escapeHtml(route.label) + ' enquiry.');
    run(E);
  }

  // Lighter flow for non-route topics (sightseeing / hotel / package / vehicle).
  function startSimpleEnquiry(serviceLabel, opts) {
    opts = opts || {};
    var E = {
      a: { service: serviceLabel },
      seq: ['name', 'mobile', 'date', 'passengers', 'note', 'consent'],
      meta: { type: opts.type || 'other', noteQuestion: opts.noteQuestion, dateQuestion: 'What date are you planning this for?' }
    };
    addBotMessage("Let's note a few details for your " + escapeHtml(serviceLabel) + ' enquiry.');
    run(E);
  }

  // Local products — completely separate from taxi bookings. No catalogue,
  // prices or stock are shown, and nothing is offered for sale.
  function startProductEnquiry() {
    var E = {
      a: { service: 'Local products enquiry' },
      seq: ['name', 'mobile', 'products', 'note', 'consent'],
      meta: { type: 'product', noteQuestion: 'Approximate quantity, and the city/state to deliver to? (or type "not sure")' }
    };
    addBotMessage("Let's note what you are looking for. This is an enquiry only — no prices or stock are listed, and it is separate from taxi bookings.");
    run(E);
  }

  // ---------------------------------------------------------------
  // "Describe my trip" — pick details out of the customer's own words.
  // Plain pattern matching, nothing leaves the browser. Anything it is not
  // sure about is simply asked again, and the summary is confirmed.
  // ---------------------------------------------------------------
  var MONTHS = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
  var MONTH_RE = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
  var VEHICLE_WORDS = [['dzire', 'Dzire'], ['ertiga', 'Ertiga'], ['innova', 'Innova / Toyota Crysta'], ['crysta', 'Innova / Toyota Crysta'], ['tempo', 'Tempo Traveller'], ['traveller', 'Tempo Traveller'], ['traveler', 'Tempo Traveller']];

  function buildDate(y, mo, d, explicitYear) {
    var today = startOfToday();
    var dt = new Date(y, mo, d);
    if (dt.getMonth() !== mo || dt.getDate() !== d) return '';
    if (!explicitYear && dt < today) dt = new Date(y + 1, mo, d);
    return isoOf(dt);
  }

  function parseDateText(t) {
    var today = startOfToday(), m;
    if (/\bday after tomorrow\b/.test(t)) return isoOf(addDays(today, 2));
    if (/\btomorrow\b/.test(t)) return isoOf(addDays(today, 1));
    if (/\btoday\b/.test(t)) return isoOf(today);
    if ((m = /\b(20\d{2})-(\d{2})-(\d{2})\b/.exec(t))) return buildDate(+m[1], +m[2] - 1, +m[3], true);
    if ((m = /\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})\b/.exec(t))) {
      var yr = +m[3]; if (yr < 100) yr += 2000;
      return buildDate(yr, +m[2] - 1, +m[1], true); // day/month/year, as written in India
    }
    if ((m = new RegExp('\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?' + MONTH_RE + '\\b(?:,?\\s+(20\\d{2}))?').exec(t))) {
      return buildDate(m[3] ? +m[3] : today.getFullYear(), MONTHS[m[2].slice(0, 3)], +m[1], !!m[3]);
    }
    if ((m = new RegExp('\\b' + MONTH_RE + '\\s+(\\d{1,2})(?:st|nd|rd|th)?\\b(?:,?\\s+(20\\d{2}))?').exec(t))) {
      return buildDate(m[3] ? +m[3] : today.getFullYear(), MONTHS[m[1].slice(0, 3)], +m[2], !!m[3]);
    }
    return '';
  }

  function cleanPlace(s) {
    var v = s.replace(/[.,;:!?]+$/g, '').replace(/\s+/g, ' ').trim();
    v = v.replace(/\b(patnitop)\b/i, 'Patnitop');
    return v.replace(/(^|\s)([a-z])/g, function (x, a, b) { return a + b.toUpperCase(); });
  }

  function parseTrip(text) {
    var found = {};
    var t = text.toLowerCase();

    // phone first, so its digits are not mistaken for a date or a head-count
    var pm = /(?:\+?91[\s-]*)?\b([6-9]\d{4}[\s-]?\d{5})\b/.exec(t);
    if (pm) {
      var cleaned = window.ptvLead ? window.ptvLead.cleanMobile(pm[1]) : pm[1].replace(/\D/g, '');
      if (cleaned) found.mobile = cleaned;
      t = t.replace(pm[0], ' ');
    }

    var nm = /\b(?:my name is|name is|name:|naam)\s+([a-z][a-z .'-]{1,40}?)(?=\s*(?:[,.;\d]|\band\b|\bfrom\b|\bto\b|\bneed\b|\bwant\b|\bphone\b|\bnumber\b|\bmobile\b|$))/.exec(t);
    if (nm && !vName(nm[1]).error) found.name = nm[1].replace(/(^|\s)([a-z])/g, function (x, a, b) { return a + b.toUpperCase(); }).trim();

    var date = parseDateText(t);
    if (date && !vDate(date).error) found.date = date;

    var pp = /\b(\d{1,2})\s*(?:people|persons?|passengers?|pax|adults?|members?|travell?ers?)\b/.exec(t) ||
             /\b(?:family of|group of|party of|we are|total)\s+(\d{1,2})\b/.exec(t);
    if (pp && !vPeople(pp[1]).error) found.passengers = String(parseInt(pp[1], 10));

    for (var i = 0; i < VEHICLE_WORDS.length; i++) {
      if (t.indexOf(VEHICLE_WORDS[i][0]) !== -1) { found.vehicle = VEHICLE_WORDS[i][1]; break; }
    }
    if (/\bround[\s-]?trip\b|\breturn trip\b|\band back\b/.test(t)) found.tripType = 'round-trip';
    else if (/\bone[\s-]?way\b|\bdrop only\b/.test(t)) found.tripType = 'one-way';

    var stop = '(?=\\s+(?:on|for|with|by|in|at|tomorrow|today|next|this|around|approx|approximately|we|and|my|please|need|want|round|one|\\d)\\b|[,.;]|$)';
    var ft = new RegExp('\\bfrom\\s+([a-z][a-z .&\'-]{1,40}?)\\s+to\\s+([a-z][a-z .&\'-]{1,40}?)' + stop).exec(t);
    if (ft) {
      found.pickup = cleanPlace(ft[1]);
      found.drop = cleanPlace(ft[2]);
      if (found.pickup.toLowerCase() === found.drop.toLowerCase()) { delete found.pickup; delete found.drop; }
    }
    return found;
  }

  var LABEL_ORDER = ['name', 'mobile', 'date', 'pickup', 'drop', 'passengers', 'vehicle', 'tripType'];

  function startDescribeFlow() {
    addBotMessage('Tell me about your trip in your own words. For example: <em>"Katra railway station to Patnitop on 25 December for 4 people, Innova"</em>. I will pick out what I can and ask only for the rest.');
    addInput({
      placeholder: 'Describe your trip…', button: 'Send →', validate: function (raw) { return raw.length > 400 ? { error: 'Please keep it under 400 characters.' } : { value: raw }; },
      onSubmit: function (text) { useDescription(text); }
    });
    backToMenuButton();
  }

  function useDescription(text) {
    var found = parseTrip(text);
    var E = {
      a: { service: 'Taxi enquiry' },
      seq: taxiSeq({ sightseeing: false, hotel: false }),
      meta: { type: 'taxi', described: true }
    };
    var rows = '';
    LABEL_ORDER.forEach(function (k) {
      if (found[k]) { E.a[k] = found[k]; rows += '<li><strong>' + LABELS[k] + ':</strong> ' + escapeHtml(found[k]) + '</li>'; }
    });
    if (rows) {
      addBotMessage('Here is what I understood:<ul class="ptv-list">' + rows + '</ul>You can change anything on the final summary. I will ask for what is missing.');
    } else {
      addBotMessage("I couldn't pick out specific details from that, so I'll ask step by step.");
    }
    run(E);
  }

  // ---------------------------------------------------------------
  // Verified fares. A fare is shown only when ALL of these hold:
  //   * pickup + drop are the two ends of a route that can be quoted
  //   * the vehicle and trip type are specific (not "not sure")
  //   * data/rates.json has a matching entry verified within 90 days
  // ---------------------------------------------------------------
  function mentions(text, words) {
    var t = String(text || '').toLowerCase();
    return words.some(function (w) { return t.indexOf(w) !== -1; });
  }

  function routeForTrip(pickup, drop) {
    var routes = AGENT_DATA.routes;
    for (var i = 0; i < routes.length; i++) {
      var q = routes[i].quoteEndpoints;
      if (!q) continue;
      if ((mentions(pickup, q[0]) && mentions(drop, q[1])) || (mentions(pickup, q[1]) && mentions(drop, q[0]))) return routes[i];
    }
    return null;
  }

  function findVerifiedRate(routeId, vehicle, tripType) {
    var rates = AGENT_DATA.rates || [];
    var now = Date.now();
    for (var i = 0; i < rates.length; i++) {
      var r = rates[i];
      if (r.route_id !== routeId || r.vehicle !== vehicle || r.trip_type !== tripType) continue;
      var verified = Date.parse(r.verified_on + 'T00:00:00');
      if (isNaN(verified)) continue;
      if ((now - verified) / 86400000 > RATE_MAX_AGE_DAYS) continue; // too old to quote
      return r;
    }
    return null;
  }

  function formatRupees(n) { return '₹' + Number(n).toLocaleString('en-IN'); }

  function quoteFor(a) {
    var route = routeForTrip(a.pickup, a.drop);
    var rate = route ? findVerifiedRate(route.id, a.vehicle, a.tripType) : null;
    if (rate) {
      return {
        html: '<div class="ptv-quote"><strong>Verified fare: ' + formatRupees(rate.amount_inr) + '</strong> (' +
          escapeHtml(a.vehicle) + ', ' + escapeHtml(rate.trip_type) + ')<br>Covers: ' + escapeHtml(rate.includes) +
          '<br><span class="ptv-note">Fare checked on ' + escapeHtml(rate.verified_on) + ' by ' + escapeHtml(rate.verified_by) +
          '. Dileep confirms the final fare and availability before anything is booked.</span></div>',
        text: 'Verified fare shown: ' + formatRupees(rate.amount_inr) + ' (' + rate.trip_type + ', checked ' + rate.verified_on + ')'
      };
    }
    if (route) {
      return {
        html: '<div class="ptv-quote">I don\'t have a verified fare for this exact trip, so I won\'t guess one. Dileep will confirm the current fare and vehicle availability on WhatsApp or a call.</div>',
        text: 'No verified fare shown'
      };
    }
    return {
      html: '<div class="ptv-quote">This trip is outside the routes I have verified fares for, so the fare and vehicle availability need manual confirmation by Dileep on WhatsApp or a call.</div>',
      text: 'No verified fare shown (manual quote needed)'
    };
  }

  // A draft outline built only from what the customer told us.
  function outlineLines(a) {
    var lines = [];
    lines.push((a.date ? a.date : 'Travel date') + ': ' + (a.pickup || 'your pickup point') + ' → ' + (a.drop || 'your drop point'));
    if (a.tripType === 'round-trip') lines.push('Return journey: timing to be agreed with Dileep');
    if (a.tripType === 'local-sightseeing') lines.push('Local sightseeing from Patnitop: stops and timing confirmed with Dileep');
    if (a.sightseeing === 'Yes') {
      var stops = (AGENT_DATA.sightseeing || []).slice(0, 3).map(function (p) { return p.name; }).join(', ');
      lines.push('Optional local sightseeing around Patnitop (' + stops + '): stops and timing confirmed with Dileep');
    }
    if (a.hotel === 'Yes') lines.push('Hotel help in Patnitop: availability is checked for your dates');
    return lines;
  }

  // ---------------------------------------------------------------
  // Confirm → (edit) → submit
  // ---------------------------------------------------------------
  function summaryRows(a) {
    var rows = '';
    ORDER.forEach(function (k) {
      if (a[k]) rows += '<div class="ptv-summary-row"><span>' + LABELS[k] + '</span><strong>' + escapeHtml(a[k]) + '</strong></div>';
    });
    return rows;
  }

  function renderConfirm(E) {
    if (!E.meta.leadId) E.meta.leadId = window.ptvLead ? window.ptvLead.newId() : 'L' + Date.now().toString(36).toUpperCase();
    addBotMessage('<div class="ptv-summary-card"><div class="ptv-summary-title">Please check your enquiry</div>' + summaryRows(E.a) + '</div>');

    E.meta.quote = { html: '', text: '' };
    if (E.meta.type === 'taxi') {
      var outline = outlineLines(E.a);
      addBotMessage('<strong>Trip outline (draft)</strong><ul class="ptv-list">' + outline.map(function (l) { return '<li>' + escapeHtml(l) + '</li>'; }).join('') + '</ul>');
      E.meta.quote = quoteFor(E.a);
      addBotMessage(E.meta.quote.html);
      var warn = capacityWarning(E.a);
      if (warn) addBotMessage('<span class="ptv-note">⚠️ ' + escapeHtml(warn) + '</span>');
      if (!E.meta.tracked) { E.meta.tracked = true; track('quote_request', { lead_type: 'taxi', source: 'agent' }); }
    } else if (E.meta.type !== 'product') {
      if (!E.meta.tracked) { E.meta.tracked = true; track('quote_request', { lead_type: E.meta.type, source: 'agent' }); }
    }

    addBotMessage('Is everything correct? Nothing is sent or booked until you confirm.');
    addButtons([
      { label: "✅ Yes, that's correct", primary: true, onClick: function () { renderSubmit(E); } },
      { label: '✏️ Change something', onClick: function () { renderEdit(E); } },
      { label: '🔄 Start Over', onClick: renderMainMenu },
    ]);
  }

  function renderEdit(E) {
    addBotMessage('What would you like to change?');
    var opts = [];
    E.seq.forEach(function (k) {
      if (E.a[k] === undefined) return;
      if (k === 'tripType' && E.a.tripType === 'local-sightseeing') return; // fixed for this route
      var label = LABELS[k] + ': ' + (String(E.a[k]).length > 18 ? String(E.a[k]).slice(0, 18) + '…' : E.a[k]);
      opts.push({ label: label, onClick: function () { delete E.a[k]; run(E); } });
    });
    opts.push({ label: '⬅ Back to summary', onClick: function () { renderConfirm(E); } });
    addButtons(opts);
  }

  function leadPayload(E) {
    var a = E.a;
    return {
      lead_id: E.meta.leadId, type: E.meta.type, source: 'agent', service: a.service,
      name: a.name, mobile: a.mobile, pickup: a.pickup || '', drop: a.drop || '',
      travel_date: a.date || '', passengers: a.passengers || '', vehicle: a.vehicle || '',
      trip_type: a.tripType || '', hotel_required: a.hotel || '', sightseeing_required: a.sightseeing || '',
      products: a.products || '', notes: a.note || '', quote_shown: E.meta.quote ? E.meta.quote.text : '',
      consent_followup: a.consent || 'No'
    };
  }

  // Records the lead once. On failure the flag is cleared so the customer can retry.
  function submitLead(E) {
    if (E.meta.submitted) return Promise.resolve({ sent: false, reason: 'already' });
    if (!window.ptvLead || !window.ptvLead.enabled()) return Promise.resolve({ sent: false, reason: 'no-endpoint' });
    E.meta.submitted = true;
    return window.ptvLead.submit(leadPayload(E)).then(function (res) {
      if (res.sent) {
        track('generate_lead', { lead_type: E.meta.type, source: 'agent' });
        if (E.meta.type === 'product') track('product_enquiry', { source: 'agent' });
      } else {
        E.meta.submitted = false;
      }
      return res;
    });
  }

  function renderSubmit(E) {
    var a = E.a;
    addBotMessage(E.meta.type === 'product'
      ? 'Thank you! This is an enquiry, not an order. Availability and prices are confirmed directly with Dileep. Send it using one of the options below.'
      : 'Thank you! This is <strong>not a confirmed booking</strong> — vehicle and hotel availability, and the exact fare, are confirmed directly by Dileep Singh. Send your enquiry using one of the options below.');

    var head = E.meta.type === 'product'
      ? 'PRODUCT ENQUIRY (not a taxi booking) — Patnitop Travels Hub (via website assistant)'
      : 'New enquiry — Patnitop Travels Hub (via website assistant)';
    var msgLines = [head];
    ORDER.forEach(function (k) { if (a[k]) msgLines.push(LABELS[k] + ': ' + a[k]); });
    msgLines.push('Ref: ' + E.meta.leadId);

    var link = el('a', 'btn btn-whatsapp ptv-inline-wa', '💬 Send on WhatsApp');
    link.href = waLink(msgLines.join('\n'));
    link.target = '_blank';
    link.rel = 'noopener';
    link.addEventListener('click', function () { submitLead(E); }); // best effort; WhatsApp opens regardless
    body.appendChild(link);
    var call = el('a', 'btn btn-pine ptv-inline-wa', '📞 Call ' + PHONE);
    call.href = 'tel:+91' + PHONE;
    body.appendChild(call);
    scrollDown();

    var actions = [];
    if (window.ptvLead && window.ptvLead.enabled()) actions.push({ label: '📨 Just send my details', onClick: function () { sendDetails(E); } });
    actions.push({ label: '🔄 Start Over', onClick: renderMainMenu });
    addButtons(actions);
  }

  function sendDetails(E) {
    addBotMessage('Sending…');
    submitLead(E).then(function (res) {
      if (res.sent) {
        addBotMessage('Your details have been sent to Dileep. He will contact you on ' + escapeHtml(E.a.mobile) + '. If you do not hear back soon, please call ' + PHONE + ' or use WhatsApp.');
        addButtons([{ label: '🔄 Start Over', onClick: renderMainMenu }]);
      } else if (res.reason === 'already') {
        addBotMessage('Your details were already sent.');
      } else {
        var why = res.reason === 'offline' ? 'You seem to be offline.' : (res.reason === 'timeout' ? 'The connection timed out.' : 'The connection failed.');
        addBotMessage(why + ' Your details have <strong>not</strong> been sent. You can try again, or use the WhatsApp or Call buttons — they work without this step.');
        addButtons([
          { label: '🔁 Try again', primary: true, onClick: function () { sendDetails(E); } },
          { label: '🔄 Start Over', onClick: renderMainMenu },
        ]);
      }
    });
  }

  // ---------------------------------------------------------------
  // Sightseeing / Hotels / Packages / Vehicles / Products menus
  // ---------------------------------------------------------------
  function renderSightseeing() {
    var html = '<strong>Patnitop Sightseeing</strong><br>Places we cover:<ul class="ptv-list">';
    AGENT_DATA.sightseeing.forEach(function (p) { html += '<li><strong>' + escapeHtml(p.name) + '</strong> — ' + escapeHtml(p.desc) + '</li>'; });
    html += '</ul><p class="ptv-note">Opening hours and entry fees can change — please confirm current details with us.</p>';
    addBotMessage(html);
    addButtons([
      { label: '📝 Start Sightseeing Enquiry', primary: true, onClick: function () {
          startSimpleEnquiry('Patnitop Sightseeing', { type: 'sightseeing', noteQuestion: 'Which places would you like to cover? (or type "not sure")' });
        } },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  function renderHotels() {
    var html = '<strong>Hotel Booking in Patnitop</strong><br>Categories we help with:<ul class="ptv-list">';
    AGENT_DATA.hotelCategories.forEach(function (h) { html += '<li><strong>' + escapeHtml(h.name) + '</strong> — ' + escapeHtml(h.desc) + '</li>'; });
    html += '</ul><p class="ptv-note">We do not confirm hotel availability here — that is checked directly on WhatsApp for your dates.</p>';
    addBotMessage(html);
    addButtons([
      { label: '📝 Start Hotel Enquiry', primary: true, onClick: function () {
          startSimpleEnquiry('Hotel Booking', { type: 'hotel', noteQuestion: 'What budget category and any preferences? (or type "not sure")' });
        } },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  function renderPackages() {
    var html = '<strong>Jammu &amp; Kashmir Tour Packages</strong><br>Destinations we assist with: ' + escapeHtml(AGENT_DATA.packageDestinations.join(', ')) + '.';
    html += '<p class="ptv-note">Exact itinerary and pricing depend on your dates, vehicle and group size — confirmed on WhatsApp.</p>';
    addBotMessage(html);
    addButtons([
      { label: '📝 Start Package Enquiry', primary: true, onClick: function () {
          startSimpleEnquiry('J&K Tour Package', { type: 'package', noteQuestion: 'Which destinations are you interested in?' });
        } },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  function renderVehicles() {
    var html = '<strong>Vehicles Available</strong><ul class="ptv-list">';
    AGENT_DATA.vehicles.forEach(function (v) { html += '<li><strong>' + escapeHtml(v.name) + '</strong> — ' + escapeHtml(v.desc) + '</li>'; });
    html += '</ul><p class="ptv-note">Fares depend on route, season and availability — call or WhatsApp for the current fare, we don\'t publish fixed prices.</p>';
    addBotMessage(html);
    addButtons([
      { label: '📝 Ask About a Vehicle', primary: true, onClick: function () {
          startSimpleEnquiry('Vehicle Enquiry', { type: 'vehicle', noteQuestion: 'Which vehicle, and for which route?' });
        } },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  function renderProducts() {
    var html = '<strong>Local Products Enquiry</strong><br>You can ask about: ' + escapeHtml(AGENT_DATA.productInterests.join(', ')) + '.';
    html += '<p class="ptv-note">This is an enquiry only — there is no online shop, price list or stock list here, and it is separate from taxi bookings. We will tell you what we can arrange.</p>';
    addBotMessage(html);
    addButtons([
      { label: '📝 Start Product Enquiry', primary: true, onClick: startProductEnquiry },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  // ---------------------------------------------------------------
  // FAQs + free-text routing (simple keyword matching only — no AI/LLM call)
  // ---------------------------------------------------------------
  function renderFaqMenu() {
    addBotMessage('Pick a question, or type your own below:');
    var opts = AGENT_DATA.faqs.map(function (f) {
      return { label: f.q, onClick: function () { addBotMessage(escapeHtml(f.a)); backToFaqOrMenu(); } };
    });
    addButtons(opts);
    addInput({
      placeholder: 'Type a question…',
      onSubmit: function (text) { handleFreeText(text); }
    });
    backToMenuButton();
  }

  function backToFaqOrMenu() {
    addButtons([
      { label: '❓ Another Question', onClick: renderFaqMenu },
      { label: '⬅ Main Menu', onClick: renderMainMenu },
    ]);
  }

  // Most specific places first; "jammu" last because it appears in many phrases.
  var ROUTE_KEYWORDS = [
    ['airport-railway', ['airport', 'railway', 'station']],
    ['nathatop-sanasar', ['nathatop', 'sanasar']],
    ['sudh-mahadev', ['sudh mahadev', 'sudhmahadev']],
    ['gauri-kund', ['gauri kund', 'gaurikund']],
    ['mantalai', ['mantalai']],
    ['kudh', ['kudh', ' kud ', ' kud?', ' kud.']],
    ['chenani', ['chenani']],
    ['udhampur', ['udhampur']],
    ['katra', ['katra', 'vaishno']],
    ['srinagar', ['srinagar', 'gulmarg', 'pahalgam', 'sonamarg']],
    ['bhaderwah', ['bhaderwah']],
    ['jammu', ['jammu']],
  ];
  var PRODUCT_WORDS = ['honey', 'dry fruit', 'dryfruit', 'rajma', 'handicraft', 'hamper', 'walnut', 'almond', 'souvenir'];
  var FARE_WORDS = ['price', 'fare', 'rate', 'cost', 'charge', 'how much', 'kitna'];

  function findRouteFor(t) {
    var padded = ' ' + t + ' ';
    for (var i = 0; i < ROUTE_KEYWORDS.length; i++) {
      var id = ROUTE_KEYWORDS[i][0], words = ROUTE_KEYWORDS[i][1];
      for (var j = 0; j < words.length; j++) {
        if (padded.indexOf(words[j]) !== -1) {
          var route = AGENT_DATA.routes.filter(function (r) { return r.id === id; })[0];
          if (route) return route;
        }
      }
    }
    return null;
  }

  function containsAny(t, words) {
    return words.some(function (w) { return t.indexOf(w) !== -1; });
  }

  function handleFreeText(text) {
    var t = text.toLowerCase();

    // 1) local products — separate flow
    if (containsAny(t, PRODUCT_WORDS)) {
      addBotMessage('That sounds like a local products enquiry — I can note it down for you.');
      renderProducts();
      return;
    }
    var routeMatch = findRouteFor(t);
    // 2) price questions: never guess a number
    if (containsAny(t, FARE_WORDS)) {
      addBotMessage('Fares depend on the route, vehicle, season and availability, so I can\'t give a price without checking. Start an enquiry and Dileep will confirm the current fare for your exact trip.');
      var fareOpts = [];
      if (routeMatch) fareOpts.push({ label: '🚕 Enquire: ' + routeMatch.label, primary: true, onClick: function () { startBookingFlow(routeMatch); } });
      else fareOpts.push({ label: '🚕 Start a Taxi Enquiry', primary: true, onClick: renderTaxiMenu });
      fareOpts.push({ label: '⬅ Main Menu', onClick: renderMainMenu });
      addButtons(fareOpts);
      return;
    }
    // 3) a trip description: offer to use it for an enquiry
    if (routeMatch) {
      var parsed = parseTrip(text);
      if (parsed.pickup || parsed.date || parsed.passengers || parsed.vehicle) {
        addBotMessage('That sounds like a taxi trip. Shall I use your description to start an enquiry?');
        addButtons([
          { label: '✅ Yes, use it', primary: true, onClick: function () { useDescription(text); } },
          { label: 'Just show route info', onClick: function () { renderRouteInfo(routeMatch); } },
        ]);
        return;
      }
      renderRouteInfo(routeMatch);
      return;
    }
    // 4) FAQ by keyword overlap
    var best = null, bestScore = 0;
    AGENT_DATA.faqs.forEach(function (f) {
      var score = keywordScore(t, f.q.toLowerCase());
      if (score > bestScore) { bestScore = score; best = f; }
    });
    if (bestScore >= 2) {
      addBotMessage(escapeHtml(best.a));
      backToFaqOrMenu();
      return;
    }
    addBotMessage('I can help with taxi bookings, sightseeing, hotels, vehicles, tour and local-product enquiries. For anything else, please continue on WhatsApp.');
    whatsAppFallback('Hello Patnitop Travels Hub, I have a question: ' + text);
    backToMenuButton();
  }

  function keywordScore(input, question) {
    var stop = { 'the': 1, 'a': 1, 'is': 1, 'do': 1, 'you': 1, 'to': 1, 'for': 1, 'i': 1, 'my': 1, 'and': 1, 'of': 1, 'in': 1,
      'how': 1, 'can': 1, 'what': 1, 'are': 1, 'does': 1, 'any': 1, 'with': 1, 'this': 1, 'that': 1, 'there': 1, 'have': 1, 'get': 1, 'your': 1 };
    var words = input.split(/\W+/).filter(function (w) { return w.length > 2 && !stop[w]; });
    var score = 0;
    words.forEach(function (w) { if (question.indexOf(w) !== -1) score++; });
    return score;
  }

  // exposed for tests only (read-only helpers, no side effects)
  window.__ptvAgentTest = { parseTrip: parseTrip, routeForTrip: routeForTrip, parseDateText: parseDateText };

})();
